package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class CharRange_ESTest_test24 extends CharRange_ESTest_scaffolding {

    /** NUL, the lowest possible char value (original literal '�'). */
    private static final char RANGE_START = (char) 0x0000;

    /** LATIN SMALL LETTER SHARP S 'ß' (original literal 'ß'). */
    private static final char RANGE_END = (char) 0x00DF;

    /**
     * Verifies that a negated range built with {@link CharRange#isNotIn(char, char)}
     * keeps its defining endpoints and negated flag, and that asking it for a
     * spliterator does not disturb that state.
     */
    @Test(timeout = 4000)
    public void test24() throws Throwable {
        CharRange negatedRange = CharRange.isNotIn(RANGE_START, RANGE_END);

        // Obtaining a spliterator must not change the range's properties.
        negatedRange.spliterator();

        assertTrue("isNotIn should produce a negated range", negatedRange.isNegated());
        assertEquals("start endpoint should be preserved", RANGE_START, negatedRange.getStart());
        assertEquals("end endpoint should be preserved", RANGE_END, negatedRange.getEnd());
    }
}
